style.css:
/* Cathedral of Shadows — Spotify */

:root {
    --my-black: #080808;       /* Main background */
    --my-dark: #111111;        /* Panels */
    --my-panel: #191919;       /* Cards */
    --my-white: #eeeeee;       /* Main text */
    --my-silver: #999999;      /* Secondary text */
    --my-accent: #bdbdbd;      /* Silver accents */
}

/* dark gothic atmosphere */
html,
body,
main {
    background: var(--my-black) !important;
    color: var(--my-white) !important;
}

/* dark panels */
main,
aside,
nav,
section {
    background-color: var(--my-dark) !important;
}

/* gothic typography */
body {
    font-family: Georgia, "Times New Roman", serif !important;
    color: var(--my-white) !important;
}

/* silver links */
a {
    color: var(--my-silver) !important;
}

a:hover {
    color: white !important;
}

/* dark cards */
[class*="card"],
[class*="Card"] {
    background: var(--my-panel) !important;
    border: 1px solid #292929 !important;
    border-radius: 5px !important;
}

/* gothic search styling */
input {
    background: #151515 !important;
    color: white !important;
    border: 1px solid #555 !important;
    border-radius: 3px !important;
}

/* buttons */
button {
    border-radius: 3px !important;
}

/* monochrome images */
img {
    border-radius: 3px !important;
}

/* scrollbar */
::-webkit-scrollbar {
    width: 8px !important;
}

::-webkit-scrollbar-track {
    background: #080808 !important;
}

::-webkit-scrollbar-thumb {
    background: #555 !important;
    border-radius: 2px !important;
}

/* subtle gothic decoration */
h1::after {
    content: "  †";
    color: #aaaaaa;
}
